// Checks the session can get a reward, then builds all texts for the reward DMs.
const input = $('When Called By Another Workflow').first().json;
const cfg = $('Load Config').first().json;
const row = $('Get Session Row').first().json ?? {};

let blockNote = null;
if (!row.id) blockNote = 'no_row';
else if (row.reward_order_id) blockNote = 'already_rewarded';
else if (!['showed_up', 'reward_blocked', 'asked', 'reminded', 'unanswered'].includes(row.followup_status)) blockNote = 'wrong_status';
// Host list from PF Config: the test host (mock) or the pilot hosts (production). Empty = all hosts.
else if (cfg.hostAllowList.length && !cfg.hostAllowList.includes((row.host_email || '').toLowerCase())) blockNote = 'host_guard';

const tag = cfg.mockMode ? '[MOCK] ' : '';
const who = row.participant_name || row.participant_email || 'the participant';
const first = row.participant_first_name || who;
const max = cfg.rewardMaxUsd;
const dflt = cfg.rewardDefaultUsd;

const out = {
    ok: blockNote === null,
    block_note: blockNote,
    invitee_uri: row.invitee_uri ?? input.invitee_uri,
    invitee_id: (row.invitee_uri || input.invitee_uri || '').split('/').pop(),
    host_email: row.host_email,
    participant_name: who,
    participant_first_name: first,
    participant_email: (row.participant_email || '').toLowerCase(),
    recipient_allowed: !cfg.mockMode || new RegExp(cfg.allowedParticipantEmailPattern).test((row.participant_email || '').toLowerCase()),
    default_amount: dflt,
    max_amount: max,
    timeout_minutes: cfg.finalTimeoutMinutes,
    tremendous_mode: cfg.tremendousMode,
    campaign_id: cfg.tremendousCampaignId,
    funding_source_id: cfg.tremendousFundingSourceId,
    currency: cfg.currency,
    mock_balance: cfg.mockBalanceUsd,
    reward_text: `${tag}Your session with ${who} has ended. Do you want to send ${first} a reward?`,
    choice_50_note: `:moneybag: You chose $${dflt}. Please confirm below.`,
    choice_other_note: ':pencil2: You chose another amount. Use the link below to enter it.',
    choice_none_note: `:no_entry_sign: OK, no reward for ${first}.`,
    choice_timeout_note: ':zzz: No answer. You can still tell Darwin later: "I want to send the reward for my last session".',
    amount_text: `${tag}How much do you want to send ${first}? Whole dollars, from 1 to ${max}.`,
    amount_retry_text: `${tag}That amount is not valid. Please enter a whole number from 1 to ${max}.`,
    amount_done_note: ':white_check_mark: Amount received. Please confirm below.',
    amount_timeout_note: ':zzz: No amount received, so nothing was sent.',
    amount_failed_note: `:no_entry_sign: No valid amount received, so nothing was sent to ${first}. You can try again through Darwin.`,
    confirm_cancel_note: ':no_entry_sign: Canceled. Nothing was sent.',
    confirm_timeout_note: ':zzz: No answer, so nothing was sent.',
};

// Reward question. Links or native buttons (PF Config slackButtons), same helper as PF Session Follow-up.
// "Other amount": with buttons it opens a Slack modal (PF Button Router), with links it opens the n8n form.
const [resumeBase, resumeQuery] = String($execution.resumeUrl).split('?');
const answerUrl = (suffix, answer) => `${resumeBase}/${suffix}?${resumeQuery}&answer=${answer}`;
let msgReward;
if (cfg.slackButtons) {
  msgReward = {
    text: out.reward_text,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: out.reward_text } },
      { type: 'actions', elements: [
        { type: 'button', action_id: 'pf_answer_reward_50', style: 'primary', text: { type: 'plain_text', text: `Send $${dflt}` }, value: answerUrl('reward', '50') },
        { type: 'button', action_id: 'pf_amount_open', text: { type: 'plain_text', text: 'Other amount' },
          // c: tells this run "other" (modal open), a: the Wait For Modal Amount address,
          // f: fallback to the form when the modal cannot open, max: the cap for the modal field.
          value: JSON.stringify({ c: answerUrl('reward', 'other'), a: `${resumeBase}/amount?${resumeQuery}`, f: answerUrl('reward', 'other_link'), max }) },
        { type: 'button', action_id: 'pf_answer_reward_none', text: { type: 'plain_text', text: 'No reward' }, value: answerUrl('reward', 'none') },
      ] },
    ],
  };
} else {
  const links = [
    `<${answerUrl('reward', '50')}|Send $${dflt}>`,
    `<${answerUrl('reward', 'other_link')}|Other amount>`,
    `<${answerUrl('reward', 'none')}|No reward>`,
  ].join('     ·     ');
  const full = `${out.reward_text}\n\n${links}`;
  msgReward = { text: full, blocks: [{ type: 'section', text: { type: 'mrkdwn', text: full } }] };
}

return [{ json: { ...out, msg_reward: msgReward } }];

// The chosen amount comes from the $50 choice, the Slack modal, or a valid form entry.
const p = $('Prepare Reward').first().json;
const cfg = $('Load Config').first().json;
const amount = $json.amount;
const tag = cfg.mockMode ? '[MOCK] ' : '';
const confirmText = `${tag}Send $${amount} to ${p.participant_name} (${p.participant_email})?`;

// Confirm question: links or native buttons (PF Config slackButtons).
const [resumeBase, resumeQuery] = String($execution.resumeUrl).split('?');
const answerUrl = (answer) => `${resumeBase}/confirm?${resumeQuery}&answer=${answer}`;
let msgConfirm;
if (cfg.slackButtons) {
  msgConfirm = {
    text: confirmText,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: confirmText } },
      { type: 'actions', elements: [
        { type: 'button', action_id: 'pf_answer_confirm_confirm', style: 'primary', text: { type: 'plain_text', text: 'Confirm' }, value: answerUrl('confirm') },
        { type: 'button', action_id: 'pf_answer_confirm_cancel', text: { type: 'plain_text', text: 'Cancel' }, value: answerUrl('cancel') },
      ] },
    ],
  };
} else {
  const full = `${confirmText}\n\n<${answerUrl('confirm')}|Confirm>     ·     <${answerUrl('cancel')}|Cancel>`;
  msgConfirm = { text: full, blocks: [{ type: 'section', text: { type: 'mrkdwn', text: full } }] };
}
return [{ json: { amount, confirm_text: confirmText, msg_confirm: msgConfirm } }];

// Validates the amount from the form: whole dollars, from 1 to the cap.
const p = $('Prepare Reward').first().json;
const raw = $('Wait For Amount').first().json['Amount in USD'];
const n = Number(String(raw ?? '').replace(/[$\s]/g, ''));
const valid = Number.isInteger(n) && n >= 1 && n <= p.max_amount;
return [{ json: { valid, amount: valid ? n : null, raw: raw ?? null } }];

// Validates the amount from the form: whole dollars, from 1 to the cap.
const p = $('Prepare Reward').first().json;
const raw = $json['Amount in USD'];
const n = Number(String(raw ?? '').replace(/[$\s]/g, ''));
const valid = Number.isInteger(n) && n >= 1 && n <= p.max_amount;
return [{ json: { valid, amount: valid ? n : null, raw: raw ?? null } }];

// Stub order: returns a fake order and pays nothing. Runs whenever the order is not live.
const b = $('Build Order').first().json;
const p = $('Prepare Reward').first().json;
const orderId = `MOCK-${$now.toFormat('yyyyLLddHHmmss')}-${p.invitee_id.slice(-6)}`;
return [{
  json: {
    request: b.body,
    order: { id: orderId, external_id: b.body.external_id, status: 'EXECUTED', payment: { total: b.amount } },
  },
}];

// Builds the Tremendous order body (API v2: one `reward` object) and decides live or stub.
// external_id = the Calendly invitee id: Tremendous returns the existing order for a repeated
// external_id, so a retry can never pay twice.
const p = $('Prepare Reward').first().json;
const cfg = $('Load Config').first().json;
const amount = $('Prepare Confirm').first().json.amount;

const body = {
  external_id: p.invitee_id,
  payment: { funding_source_id: p.funding_source_id },
  reward: {
    campaign_id: p.campaign_id,
    value: { denomination: amount, currency_code: p.currency },
    delivery: { method: 'EMAIL' },
    recipient: { name: p.participant_name, email: p.participant_email },
  },
};

// Live orders only on production. PF Config already sets stub everywhere else; this is a second check.
const live = cfg.tremendousMode === 'live' && cfg.environment === 'production' && !cfg.mockMode;
return [{ json: { live, amount, body } }];

// One result shape for the live and the stub order.
// Live: 200 = order created, 201 = order with this external_id already exists (no second payment),
// 402 = not enough funds, anything else = error (the row stays as it is, so the host can retry).
const live = $('Build Order').first().json.live;
if (!live) {
  const s = $('Tremendous Order (stub)').first().json;
  return [{ json: { result: 'ok', order_id: s.order.id, order_status: s.order.status, stub: true } }];
}
const res = $('Create Tremendous Order').first().json ?? {};
const code = Number(res.statusCode);
const body = res.body ?? {};
if ((code === 200 || code === 201) && body.order?.id) {
  return [{ json: { result: 'ok', order_id: body.order.id, order_status: body.order.status, duplicate: code === 201, stub: false } }];
}
const detail = JSON.stringify(body.errors ?? body.message ?? body).slice(0, 300);
if (code === 402) {
  return [{ json: { result: 'no_funds', error_text: `Tremendous answered 402 (not enough funds). ${detail}`, stub: false } }];
}
return [{ json: { result: 'error', error_text: `Tremendous answered ${code || 'no response'}. ${detail}`, stub: false } }];

// Validates the amount from the Slack modal: whole dollars, from 1 to the cap.
// The modal field already has min 1 and max 100; this is the check on our side.
const p = $('Prepare Reward').first().json;
const raw = $('Wait For Modal Amount').first().json.query?.amount;
const n = Number(String(raw ?? '').replace(/[$\s]/g, ''));
const valid = raw !== undefined && Number.isInteger(n) && n >= 1 && n <= p.max_amount;
return [{ json: { valid, amount: valid ? n : null, raw: raw ?? null } }];
